"""Additional guided practice used by PowerPoints and notebooks."""
EXTRAS = {3: [('A branch with a clear boundary', 'Read from the top. >= includes the boundary. Only the selected branch runs. Try the value exactly at 10 as well as 9 and 11.', 'def check_level(value):\n    if value >= 10:\n        return "high"\n    return "low"\n\nprint(check_level(10))\nprint(check_level(9))'), ('Selecting a largest error without loops', 'A list holds several values. abs removes the sign when measuring the SIZE of an error. max returns the largest supplied value. Keep the original signed error when the task asks for direction.', 'errors = [-2, 5, -8]\nlargest = max(abs(errors[0]), abs(errors[1]), abs(errors[2]))\nprint(largest)')], 4: [('A record and a growing list', 'Braces pair a key with its value. append adds one value to the end of a list. The same pattern works after reading a CSV row.', 'records = [{"sensor": "A", "reading": "2.5"},\n           {"sensor": "B", "reading": "3.5"}]\nvalues = []\nfor row in records:\n    values.append(float(row["reading"]))\nprint(values)')], 5: [('Unique labels and the largest group', 'nunique counts distinct labels, not rows. idxmax returns the label of the largest total. Here there is no tie.', 'print(df["building"].nunique())\ntotals = df.groupby("building")["kwh"].sum()\nprint(totals.idxmax())')], 6: [('Copying records and recognising repeats', 'set() creates a collection of already-seen identifiers. in checks membership. continue skips the rest of that iteration. dict(row) copies a record so later edits do not change the original. Different record IDs from the same equipment remain legitimate observations.', 'raw_records = [{"id": 1, "equipment": "A", "value": 10},\n               {"id": 1, "equipment": "A", "value": 10},\n               {"id": 2, "equipment": "A", "value": 12}]\nseen = set()\nkept = []\nfor row in raw_records:\n    if row["id"] in seen:\n        continue\n    seen.add(row["id"])\n    kept.append(dict(row))\nprint(len(raw_records), len(kept))'), ('Summaries returned as a dictionary', 'This example expects a nonempty list. It calculates a count and mean, then returns a dictionary with named outputs. Use the exact keys specified by the issued task when adapting this pattern.', 'def describe(values):\n    count = len(values)\n    mean = sum(values) / count\n    return {"count": count, "mean": mean}\n\nprint(describe([10, 12]))'), ('Reading a blank field', 'CSV values start as text. The if/else below stores None for a blank. Otherwise float converts the text into a number.', 'text_values = ["20", "", "24"]\nparsed = []\nfor text in text_values:\n    if text == "":\n        parsed.append(None)\n    else:\n        parsed.append(float(text))\nprint(parsed)')], 8: [('Preprocessing learned from training only', 'SimpleImputer learns one median for each training column. make_pipeline connects this step to the model. fit learns both steps using only the training examples. predict reuses them on new inputs. No target is supplied to predict. The two inputs here are invented practice measurements.', 'from sklearn.impute import SimpleImputer\nfrom sklearn.pipeline import make_pipeline\nimport numpy as np\ntrain_inputs = [[1, 20], [2, 22], [3, np.nan], [4, 24]]\ntrain_targets = [12, 14, 16, 18]\nimputer = SimpleImputer(strategy="median")\nmodel = LinearRegression()\npipeline = make_pipeline(imputer, model)\npipeline.fit(train_inputs, train_targets)\npredictions = pipeline.predict([[2.5, np.nan]])\nprint(predictions.round(2).tolist())'), ('Reading records into a feature table', 'Each inner list is one row, in the same order as the input records. The target list uses that same row order. The feature table has no answer column.', 'rows = [{"length": 2, "width": 3, "area": 6},\n        {"length": 4, "width": 5, "area": 20}]\nX = []\ny = []\nfor row in rows:\n    X.append([row["length"], row["width"]])\n    y.append(row["area"])\nprint(X)\nprint(y)'), ('Two error measures', 'zip pairs corresponding values. abs measures error size. Squaring emphasises large errors; taking the square root returns to the original unit. These functions assume equal-length, nonempty paired observations.', 'from math import sqrt\na = [10, 20]\np = [12, 16]\nabsolute = []\nsquared = []\nfor truth, guess in zip(a, p):\n    difference = truth - guess\n    absolute.append(abs(difference))\n    squared.append(difference ** 2)\nprint(sum(absolute) / len(a))\nprint(sqrt(sum(squared) / len(a)))')], 9: [('Counting arbitrary paired observations', 'Start every counter at zero before the loop. == compares labels. and means both comparisons must be true. elif checks another condition only when earlier ones were false.', 'tp = tn = fp = fn = 0\nfor truth, guess in zip(actual, predicted):\n    if truth == 1 and guess == 1:\n        tp += 1\n    elif truth == 0 and guess == 0:\n        tn += 1\n    elif truth == 0 and guess == 1:\n        fp += 1\n    else:\n        fn += 1\nprint(tp, tn, fp, fn)')], 10: [('A training-only fill value', 'The median is learned from training observations. Adding a new validation observation must not change it. A real modelling pipeline follows this same rule for each learned step.', 'from statistics import median\ntraining_values = [20, 22, 24]\nvalidation_values = [None, 40]\ntraining_median = median(training_values)\nfilled_validation = []\nfor value in validation_values:\n    if value is None:\n        filled_validation.append(training_median)\n    else:\n        filled_validation.append(value)\nprint(training_median, filled_validation)')], 11: [('Two models under one protocol', 'Run this complete practice experiment in a fresh session. Both models use the same rows and targets; the second receives one additional input. Read every column before fitting. This invented experiment illustrates procedure, not a measured engineering benefit.', 'from sklearn.linear_model import LinearRegression\nfrom sklearn.metrics import mean_absolute_error\ntrain = [[1, 2], [2, 3], [3, 2], [4, 4], [5, 3]]\ny = [3, 5, 5, 8, 8]\nvalidation = [[2, 2], [3, 3]]\ntruth = [4, 6]\ndef with_interaction(rows):\n    result = []\n    for a, b in rows:\n        result.append([a, b, a * b])\n    return result\nbase = LinearRegression().fit(train, y)\nextended = LinearRegression().fit(with_interaction(train), y)\nbase_predictions = base.predict(validation)\nbase_error = mean_absolute_error(truth, base_predictions)\nprint(round(base_error, 6))\nvalidation_features = with_interaction(validation)\nextended_predictions = extended.predict(validation_features)\nerror = mean_absolute_error(truth, extended_predictions)\nprint(round(error, 6))')], 12: [('Sorting with a tie-break rule', 'A tuple is an ordered group of values. Python compares the first item, then the second when tied, then the third. The key function gives sorted the tuple for each candidate. Guard an empty list before selecting position zero.', 'def rank(item):\n    return (item["error"], item["ms"], item["name"])\n\nordered = sorted(eligible, key=rank)\nif len(ordered) == 0:\n    winner = None\nelse:\n    winner = ordered[0]["name"]\nprint(winner)')]}
EXTRAS[8][:0] = [('The mean baseline', 'Use the same training data. This baseline learns their mean, 15, and predicts it for every input. It gives a simple comparison before claiming the line helps.', 'from sklearn.dummy import DummyRegressor\nbaseline = DummyRegressor(strategy="mean")\nbaseline.fit(X_train, y_train)\nprint(baseline.predict(new_inputs).tolist())'), ('A small regression tree', 'A tree learns threshold questions from the training inputs. Each final group, or leaf, predicts a target value. This tree returns 14 for input 2.5 in this toy example. max_depth limits the number of successive decisions. random_state fixes the random seed.', 'from sklearn.tree import DecisionTreeRegressor\ntree = DecisionTreeRegressor(max_depth=4, random_state=17)\ntree.fit(X_train, y_train)\nprint(tree.predict(new_inputs).tolist())')]
EXTRAS[4].append(('Summaries for separate groups', 'A dictionary can hold one running total for each group. An absent key needs an initial zero. Then add the reading to that group. To calculate group means, keep a matching count and divide each group total by its own count.', 'records = [{"group": "A", "reading": 2},\n           {"group": "A", "reading": 4},\n           {"group": "B", "reading": 9}]\ntotals = {}\nfor row in records:\n    group = row["group"]\n    if group not in totals:\n        totals[group] = 0\n    totals[group] = totals[group] + row["reading"]\nprint(totals)'))
EXTRAS[6].append(('A chart with labelled axes', 'matplotlib draws charts. subplots creates a Figure, the whole page, and Axes, the plotting area. scatter pairs each input with its corresponding reading. The horizontal axis is the input and the vertical axis is the reading. A pattern alone does not prove causation. In the test, return Figure objects as the brief specifies.', 'import matplotlib.pyplot as plt\ninputs = [1, 2, 3, 4]\nreadings = [12, 14, 13, 18]\nfig, ax = plt.subplots()\nax.scatter(inputs, readings)\nax.set_xlabel("Input (teaching units)")\nax.set_ylabel("Reading (teaching units)")\nax.set_title("Four invented observations")\nplt.show()'))
EXTRAS[6].append(('Comparing groups and a distribution', 'bar compares one value for each named group. hist counts observations in value intervals called bins. Read the bar labels and both axes. This practice uses two bins; follow the exact bin rule in the test brief. Save and keep the Figure objects when a task asks for them.', 'bar_fig, bar_ax = plt.subplots()\nbar_ax.bar(["A", "B"], [13, 16])\nbar_ax.set_xlabel("Group")\nbar_ax.set_ylabel("Mean reading (teaching units)")\nbar_ax.set_title("Two invented group means")\nhist_fig, hist_ax = plt.subplots()\nhist_ax.hist(readings, bins=2)\nhist_ax.set_xlabel("Reading (teaching units)")\nhist_ax.set_ylabel("Count of observations")\nhist_ax.set_title("Distribution of four observations")\nplt.show()'))
